#!/usr/bin/env node
/**
 * enrich-breed-pages.mjs
 * Post-processes existing health-problems.md and puppy-essentials.md files
 * that were generated by Sprint 5 but not re-generated by the main pipeline.
 *
 * Changes applied:
 * - Adds breed-specific image field (deterministic hash-based index from image_urls[])
 * - Sets indexInBlog: true for health pages (puppy stays false)
 * - Replaces the thin "About [Breed]" one-liner with the full breed description,
 *   origin context, AKC popularity, trait table, and intelligence context.
 */

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../..');
const BLOG_DIR = path.join(ROOT, 'src/content/blog');
const APPLY = process.argv.includes('--apply');

function readJson(rel, fallback) {
  try { return JSON.parse(fs.readFileSync(path.join(ROOT, rel), 'utf8')); }
  catch { return fallback; }
}

const breeds = [
  ...readJson('src/data/master-breeds.json', []),
  ...readJson('src/data/master-crossbreeds.json', []),
];
const breedMap = new Map(breeds.map((b) => [b.slug, b]));

// Simple DJB2 hash (matches djb2Hash in generator)
function djb2Hash(str) {
  let h = 5381;
  for (let i = 0; i < str.length; i++) h = ((h << 5) + h) + str.charCodeAt(i);
  return Math.abs(h);
}

function pickBreedImageUrl(breed, familyKey) {
  const urls = Array.isArray(breed?.image_urls) ? breed.image_urls : [];
  if (!urls.length) return '';
  if (urls.length === 1) return urls[0];
  return urls[djb2Hash(`${breed.slug}-${familyKey}`) % urls.length];
}

function buildBreedProfile(breed) {
  const desc = String(breed?.description || '').trim();
  const origin = breed?.origin_country;
  const fciGroup = breed?.fci_group_name;
  const akcPop = Number(breed?.akc_popularity || 0);
  const name = breed?.name || '';
  const metaParts = [];
  if (origin && fciGroup) {
    metaParts.push(`Originally from ${origin}, the ${name} belongs to the ${fciGroup} group.`);
  } else if (origin) {
    metaParts.push(`Originally from ${origin}.`);
  }
  if (akcPop > 0 && akcPop <= 20) {
    metaParts.push(`The ${name} ranks #${akcPop} in AKC breed popularity — one of the most widely owned breeds in the United States.`);
  } else if (akcPop > 0 && akcPop <= 50) {
    metaParts.push(`The ${name} ranks #${akcPop} in AKC breed popularity.`);
  }
  const parts = [];
  if (desc) parts.push(desc);
  if (metaParts.length) parts.push(metaParts.join(' '));
  return parts.join('\n\n');
}

function buildTraitSummary(breed) {
  const name = breed?.name || '';
  const traits = breed?.traits || {};
  function traitBar(value, labels) {
    const v = Number(value ?? -1);
    if (v < 0) return null;
    const blocks = Math.round(v * 5);
    const bar = '█'.repeat(blocks) + '░'.repeat(5 - blocks);
    const label = labels[Math.min(Math.floor(v * (labels.length - 0.01)), labels.length - 1)];
    return `${bar} ${label}`;
  }
  const rows = [
    ['Energy', traitBar(traits.energy_value, ['Low', 'Below Average', 'Moderate', 'High', 'Very High'])],
    ['Shedding', traitBar(traits.shedding_value, ['Minimal', 'Light', 'Moderate', 'Heavy', 'Very Heavy'])],
    ['Grooming needs', traitBar(traits.grooming_value, ['Very Low', 'Low', 'Moderate', 'High', 'Very High'])],
    ['Trainability', traitBar(traits.trainability_value, ['Challenging', 'Below Average', 'Moderate', 'High', 'Exceptional'])],
    ['Sociability', traitBar(traits.demeanor_value, ['Reserved', 'Selective', 'Balanced', 'Friendly', 'Very Friendly'])],
  ].filter(([, bar]) => bar !== null);
  if (!rows.length) return '';
  return `### ${name} at a glance\n\n| Trait | Level |\n|-------|-------|\n${rows.map(([n, bar]) => `| ${n} | ${bar} |`).join('\n')}`;
}

function buildIntelligenceContext(breed) {
  const name = breed?.name || '';
  const rd = breed?.ranking_data || {};
  const rank = Number(rd.intelligence_rank || 0);
  const label = String(rd.intelligence_label || '').trim();
  if (!rank || !label) return '';
  const trainValue = Number(breed?.traits?.trainability_value ?? -1);
  const trainNote = trainValue >= 0.8
    ? 'responds quickly to reward-based methods and picks up new cues with very few repetitions'
    : trainValue >= 0.5
    ? 'responds well to consistent, positive reinforcement training'
    : 'benefits from patient repetition and high-value rewards';
  const topNote = rank <= 10 ? 'top 10' : rank <= 25 ? 'top 25' : 'top 50';
  return `Ranked **#${rank}** in canine intelligence (${label} tier), the ${name} ${trainNote} — placing it among the ${topNote} most trainable breeds.`;
}

function parseFrontmatter(text) {
  if (!text.startsWith('---')) return { data: {}, body: text, rawFm: '' };
  const end = text.indexOf('\n---', 3);
  if (end === -1) return { data: {}, body: text, rawFm: '' };
  const rawFm = text.slice(4, end);
  const afterFm = text.slice(end + 4).replace(/^\n/, '');
  const data = {};
  for (const line of rawFm.split(/\r?\n/)) {
    const m = line.match(/^([A-Za-z][A-Za-z0-9_]*):\s*(.*)$/);
    if (!m) continue;
    let v = m[2].trim();
    if ((v.startsWith('"') && v.endsWith('"')) || (v.startsWith("'") && v.endsWith("'"))) v = v.slice(1, -1);
    data[m[1]] = v;
  }
  return { data, body: afterFm, rawFm };
}

function enrichFile(filePath, familyKey) {
  const raw = fs.readFileSync(filePath, 'utf8');
  const { data, body, rawFm } = parseFrontmatter(raw);
  const breedSlug = data.breedSlug;
  if (!breedSlug) return null;

  const breed = breedMap.get(breedSlug);
  if (!breed) return { slug: breedSlug, reason: 'breed not found in master data' };

  const imageUrl = pickBreedImageUrl(breed, familyKey);
  const hasImage = Boolean(data.image);
  const isHealthIndexed = data.indexInBlog === 'true';

  // Only update files that need changes
  const needsImageUpdate = imageUrl && !hasImage;
  const needsIndexUpdate = familyKey === 'health' && !isHealthIndexed;
  // Needs body update if: no trait table, merged origin text, or duplicate trait tables
  const hasMergedOrigin = /[a-z] Originally from/.test(body);
  const hasDuplicateTraits = (body.match(/^### .+ at a glance$/gm) || []).length > 1;
  const needsBodyUpdate = !/^### .+ at a glance$/m.test(body) || hasMergedOrigin || hasDuplicateTraits;

  if (!needsImageUpdate && !needsIndexUpdate && !needsBodyUpdate) {
    return { slug: breedSlug, skipped: true, reason: 'already up to date' };
  }

  // Update frontmatter string
  let newFm = rawFm;
  if (needsIndexUpdate) {
    newFm = newFm.replace(/^indexInBlog:\s*false$/m, 'indexInBlog: true');
  }
  if (needsImageUpdate) {
    newFm = newFm.replace(/^(canonicalUrl:.*)$/m, `image: "${imageUrl}"\n$1`);
  }

  // Update body - replace About section one-liner with enriched content
  let newBody = body;
  if (needsBodyUpdate) {
    const breedProfile = buildBreedProfile(breed);
    const traitSummary = buildTraitSummary(breed);
    const intelligenceCtx = familyKey === 'health' || familyKey === 'puppy' ? buildIntelligenceContext(breed) : '';

    // Replace the entire About section up to the first established content section
    // For health pages, content follows "### Common health concerns"
    // For puppy pages, content follows "## How to approach"
    const nameEsc = breed.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const terminator = familyKey === 'health'
      ? `### Common health concerns for ${nameEsc}`
      : `## How to approach`;
    const terminatorEsc = terminator.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
    const aboutPattern = new RegExp(
      `(## About ${nameEsc}s?)\n[\\s\\S]*?(?=${terminatorEsc})`,
      'm'
    );

    const enrichedAbout = breedProfile || '';
    const insertion = [enrichedAbout, traitSummary, intelligenceCtx].filter(Boolean).join('\n\n');

    if (insertion && aboutPattern.test(newBody)) {
      newBody = newBody.replace(aboutPattern, `$1\n${insertion}\n`);
    }
  }

  const newContent = `---\n${newFm}\n---\n${newBody}`;
  if (APPLY) fs.writeFileSync(filePath, newContent, 'utf8');
  return { slug: breedSlug, updated: true, needsImageUpdate, needsIndexUpdate, needsBodyUpdate };
}

// Process all health and puppy files
const files = fs.readdirSync(BLOG_DIR).filter((f) => f.endsWith('.md'));
const healthFiles = files.filter((f) => f.endsWith('-health-problems.md'));
const puppyFiles = files.filter((f) => f.endsWith('-puppy-essentials.md'));

console.log(`Processing ${healthFiles.length} health files + ${puppyFiles.length} puppy files`);

let updated = 0, skipped = 0, errors = 0;
for (const file of healthFiles) {
  const result = enrichFile(path.join(BLOG_DIR, file), 'health');
  if (!result) { errors++; continue; }
  if (result.skipped) { skipped++; } else { updated++; }
}
for (const file of puppyFiles) {
  const result = enrichFile(path.join(BLOG_DIR, file), 'puppy');
  if (!result) { errors++; continue; }
  if (result.skipped) { skipped++; } else { updated++; }
}

console.log(`\n${APPLY ? '✓ Applied' : '(dry-run)'} — Updated: ${updated}, Skipped: ${skipped}, Errors: ${errors}`);
if (!APPLY) console.log('Run with --apply to write changes.');
